                for idx in range(len(opts.hosts)):
                    all_vals += [x for t,x,ok in samples[idx] if now - t <= opts.buffer]
                ymax = max(all_vals) if all_vals else 0.001
                ymin = min(all_vals) if all_vals else 0.0
                if ymax <= ymin: ymax = ymin + 0.001
                for idx in range(len(opts.hosts)):
                    color = colors[idx] if idx < len(colors) else DEFAULT_COLORS[idx % len(DEFAULT_COLORS)]
                    recent = [(t,x) for t,x,ok in samples[idx] if now - t <= opts.buffer]
                    for t,x in recent[-(cols-left-2):]:
                        age = now - t
                        xcol = int((cols-2) - (age / max(1, opts.buffer)) * (cols-left-2))
                        if xcol < left or xcol >= cols: continue
                        frac = (x - ymin) / (ymax - ymin)
                        yrow = bottom - 1 - int(frac * max(1, bottom-top-1))
                        yrow = max(top, min(bottom-1, yrow))
                        ch = chars[int((x*1000000)) % len(chars)]
                        sys.stdout.write(f"\x1b[{yrow};{xcol}H\x1b[38;5;{color};49m{ch}")
                # Time labels
                sys.stdout.write(f"\x1b[{rows};1H\x1b[39;49m" + time.strftime('%H:%M:%S', time.localtime(now-opts.buffer))[:cols])
                mid = time.strftime('%H:%M:%S', time.localtime(now-opts.buffer/2))
                if cols > 45: sys.stdout.write(f"\x1b[{rows};{cols//2}H{mid}")
                end = time.strftime('%H:%M:%S', time.localtime(now))
                if cols > 12: sys.stdout.write(f"\x1b[{rows};{max(1,cols-7)}H{end}")
            sys.stdout.write("\x1b[39m\x1b[49m\x1b[0m\x1b[?25l")
            sys.stdout.flush()
            time.sleep(0.2)
    finally:
        sys.stdout.write("\x1b[?25h\x1b[1;1H")
        if opts.clear:
            sys.stdout.write("\x1b[?1049l")
        sys.stdout.flush()

def handle_signal(signum, frame):
    stop_event.set()

def run_cmd_mode(opts, colors):
    interval = opts.watch_interval if opts.watch_interval is not None else 0.5
    samples = [[] for _ in opts.hosts]
    # Original runs commands once before failing to open a terminal.
    for idx, cmd in enumerate(opts.hosts):
        elapsed, ok = run_command_once(cmd)
        samples[idx].append((time.time(), elapsed, ok))
    if not (sys.stdout.isatty() and sys.stdin.isatty()):
        eprint(NO_TTY_ERROR); raise CliExit(1)
    threads = []
    for idx, cmd in enumerate(opts.hosts):
        t = threading.Thread(target=command_worker, args=(cmd, interval, samples, idx), daemon=True)
        t.start(); threads.append(t)
    render_tui(opts, samples, colors)
    for t in threads:
        t.join(timeout=0.2)

def run_ping_mode(opts, colors):
    resolve_hosts(opts)
    procs = spawn_ping(opts)
    if not (sys.stdout.isatty() and sys.stdin.isatty()):
        for p in procs:
            try: p.kill()
            except Exception: pass
        eprint(NO_TTY_ERROR); raise CliExit(1)
    # A lightweight placeholder graph; we don't parse ping output deeply, but keep processes alive.
    samples = [[] for _ in opts.hosts]
    for i in range(len(opts.hosts)):
        samples[i].append((time.time(), 0.0, True))
    try:
        render_tui(opts, samples, colors)
    finally:
        for p in procs:
            try: p.terminate()
            except Exception: pass

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)
    try:
        opts = parse_args(sys.argv[1:])
        if not opts.hosts:
            eprint(MISSING_TARGETS); return 1
        colors = validate_colors(opts)
        if opts.cmd:
            run_cmd_mode(opts, colors)
        else:
            run_ping_mode(opts, colors)
        return 0
    except CliExit as e:
        return e.code
    except BrokenPipeError:
        return 1

if __name__ == '__main__':
    sys.exit(main())
